+func TestSyncReturnsTheFlushErrorUnlessSyncingIsSkipped(t *testing.T) {
+	t.Cleanup(func() { skip.Store(false) })
+	f, err := os.Create(filepath.Join(t.TempDir(), "closed"))
+	if err != nil {
+		t.Fatal(err)
+	}
+	if err := f.Close(); err != nil {
+		t.Fatal(err)
+	}
+
+	// With syncing enabled, the flush of a closed file fails and Sync returns that error.
+	skip.Store(false)
+	if err := Sync(f); err == nil {
+		t.Fatal("Sync of a closed file with syncing enabled = nil, want the flush error")
+	}
+
+	// With syncing skipped, nothing is flushed, so there is no error to return.
+	skip.Store(true)
+	if err := Sync(f); err != nil {
+		t.Fatalf("Sync of a closed file with syncing skipped = %v, want nil", err)
+	}
+}
